103	static std::string resolveSubProjectAbsPath( const std::string& aSubProjectUuid,
104	                                             std::string*       aErrorOut )
105	{
106	    std::string containerJson = g_containerJsonProvider ? g_containerJsonProvider() : "";
107	
108	    if( containerJson.empty() )
109	    {
110	        if( aErrorOut )
111	            *aErrorOut = "target.sub_project_uuid was specified but the active "
112	                         "project is not a multi-board container.";
113	        return "";
114	    }
115	
116	    auto cj = nlohmann::json::parse( containerJson, nullptr, false );
117	
118	    if( cj.is_discarded() || !cj.contains( "sub_projects" ) )
119	    {
120	        if( aErrorOut )
121	            *aErrorOut = "target.sub_project_uuid lookup failed: container "
122	                         "metadata is malformed.";
123	        return "";
124	    }
125	
126	    for( const auto& sp : cj["sub_projects"] )
127	    {
128	        if( sp.value( "uuid", "" ) == aSubProjectUuid )
129	            return sp.value( "absolute_path", "" );
130	    }
131	
132	    if( aErrorOut )
133	    {
134	        std::string available;
135	
136	        for( const auto& sp : cj["sub_projects"] )
137	        {
138	            if( !available.empty() )
139	                available += ", ";
140	
141	            available += sp.value( "uuid", "" ) + " (" + sp.value( "name", "?" ) + ")";
142	        }
143	
144	        *aErrorOut = "target.sub_project_uuid '" + aSubProjectUuid
145	                     + "' does not match any sub-project. Available: "
146	                     + ( available.empty() ? "none" : available );
147	    }
148	
149	    return "";
150	}
