155	 * backslash + single-quote handling. (Used only for short-known-clean
156	 * payloads; for free-form messages prefer pyRawTripleQuoted below.)
157	 */
158	static std::string escapePyString( const std::string& aIn )
159	{
160	    std::string esc;
161	    esc.reserve( aIn.size() + 8 );
162	
163	    for( char c : aIn )
164	    {
165	        if( c == '\\' )
166	            esc += "\\\\";
167	        else if( c == '\'' )
168	            esc += "\\'";
