177	/**
178	 * Wrap a free-form message in a Python `r"""..."""` literal — raw
179	 * triple-double-quoted string. Robust against any embedded single
180	 * quotes, double quotes, newlines, or backslashes; the only sequence
181	 * that would break it is a literal `"""` in the message, which we
182	 * defensively neutralise.
183	 *
184	 * Used for emitting `raise RuntimeError(...)` preambles where the
185	 * message contains arbitrary content (tool names, paths, JSON-ish
186	 * fragments) that's hard to escape character-by-character correctly.
187	 */
188	static std::string pyRawTripleQuoted( const std::string& aIn )
189	{
190	    std::string body = aIn;
191	    size_t      pos = 0;
192	
193	    // Defensively split any literal """ sequence. " " " is an equivalent
194	    // sequence for human readers but Python parses it as three separate
195	    // empty strings, breaking out of our triple-quote envelope. Inserting
196	    // a zero-width-ish split (a backslash escape) keeps the message
197	    // readable and the literal valid.
198	    while( ( pos = body.find( "\"\"\"", pos ) ) != std::string::npos )
199	    {
200	        body.replace( pos, 3, "\"\\\"\"\"" );
201	        pos += 5;
202	    }
203	
204	    return "r\"\"\"" + body + "\"\"\"";
205	}
