208	/**
209	 * Tools that don't make sense on the multi-board canvas. When called
210	 * with `target.doc_type:"mbs"`, the build preamble emits an explicit
211	 * RuntimeError so the LLM gets a clear "this op isn't valid on MBS"
212	 * signal instead of a silently-wrong result. Listed reasons:
213	 *   - sch_annotate: module blocks have MBS-scoped annotation (B1, B2)
214	 *     applied by mbs_refresh, not the schematic annotator
215	 *   - sch_run_simulation: SPICE doesn't apply to a cross-board topology
216	 *   - sch_place_companions: no IC support circuitry on the MBS canvas
217	 *   - sch_draft_circuit: circuit drafting doesn't apply
218	 *   - sch_find_symbol: MBS doesn't add library symbols
219	 *   - sch_symbols: schematic symbol enumeration; MBS uses module blocks
220	 *   - sch_add_sheet / sch_update_sheet / sch_switch_sheet: MBS is flat
221	 *
222	 * Tools that DO work on MBS (sch_add wires/labels/text/graphics,
223	 * sch_label, sch_connect_net, sch_get_summary, sch_inspect, sch_save,
224	 * sch_run_erc, sch_delete, sch_update) are not in this set.
225	 */
226	static bool toolUnsupportedOnMbs( const std::string& aToolName )
227	{
228	    static const std::set<std::string> unsupported = {
229	        "sch_annotate",
230	        "sch_run_simulation",
231	        "sch_place_companions",
232	        "sch_draft_circuit",
233	        "sch_find_symbol",
234	        "sch_symbols",
235	        "sch_add_sheet",
236	        "sch_update_sheet",
237	        "sch_switch_sheet",
238	    };
239	
240	    return unsupported.count( aToolName ) > 0;
241	}
