278	/**
279	 * Build the Python lines that rebind `sch` / `board` to the right document.
280	 *
281	 * Routing modes:
282	 *  - target.doc_type == "mbs" with app:sch — `mbs` is already bound by
283	 *    the bootstrap (effective mode is "mbs"); we just alias `sch = mbs`.
284	 *    Tools listed in `toolUnsupportedOnMbs` reject before reaching here.
285	 *  - target.doc_type == "mbs" with app:pcb — rejected, no MBS PCB exists.
286	 *  - sub_project_uuid set with app:sch/pcb — rebind to the sub-project's
287	 *    schematic / board via the new kipy by-project-path helpers.
288	 *
289	 * Empty string return = no rebind needed. May also emit `raise
290	 * RuntimeError(...)` when the uuid or unsupported-tool checks fail.
291	 */
292	static std::string buildTargetPreamble( const std::string& aToolName,
293	                                        const std::string& aApp,
294	                                        const nlohmann::json& aInput )
295	{
296	    if( !aInput.is_object() || !aInput.contains( "target" ) )
297	        return "";
298	
299	    const auto& target = aInput["target"];
300	
301	    if( !target.is_object() )
302	        return "";
303	
304	    // The mbs app has only one possible target — the container — so target
305	    // is ignored there. SCH and PCB apps are the interesting cases.
306	    if( aApp != "sch" && aApp != "pcb" )
307	        return "";
308	
309	    std::string docType = target.value( "doc_type", "" );
310	
311	    if( docType == "mbs" )
312	    {
313	        // PCB tools have no MBS counterpart — reject explicitly.
314	        if( aApp == "pcb" )
315	        {
316	            std::string msg = "target.doc_type=\"mbs\" is not valid for PCB tools "
317	                              "— the multi-board schematic has no PCB. Use a "
318	                              "sub-project PCB target instead.";
319	            return "raise RuntimeError(" + pyRawTripleQuoted( msg ) + ")\n";
320	        }
321	
322	        // Tools that don't make sense on the MBS canvas (annotation,
323	        // simulation, IC support placement, etc.) reject before doing
324	        // anything destructive — see toolUnsupportedOnMbs above.
325	        if( toolUnsupportedOnMbs( aToolName ) )
326	        {
327	            std::string msg = "Tool '" + aToolName + "' is not supported on the "
328	                              "multi-board (MBS) canvas. It targets schematic-only "
329	                              "constructs (e.g. symbol annotation, SPICE simulation, "
330	                              "IC support circuitry, or hierarchical sub-sheets) "
331	                              "that the MBS does not have. Use mbs_refresh / "
332	                              "mbs_run_erc / sch_add (with target.doc_type=\"mbs\" "
333	                              "for wires/labels/text) instead.";
334	
335	            return "raise RuntimeError(" + pyRawTripleQuoted( msg ) + ")\n";
336	        }
337	
338	        // Bootstrap (in BuildModeInitCode for "mbs" mode) already bound
339	        // `mbs`. Alias `sch = mbs` so unmodified sch_* scripts keep
340	        // working without rewriting their `sch.symbols.add(...)` calls.
341	        return "sch = mbs\n";
342	    }
343	
344	    // Per-sub-project routing.
345	    std::string subUuid = target.value( "sub_project_uuid", "" );
346	
347	    if( subUuid.empty() )
348	        return "";
349	
350	    std::string error;
351	    std::string absPath = resolveSubProjectAbsPath( subUuid, &error );
352	
353	    if( absPath.empty() )
354	        return "raise RuntimeError(" + pyRawTripleQuoted( error ) + ")\n";
355	
356	    std::string pyPath = pyRawTripleQuoted( absPath );
357	
358	    if( aApp == "sch" )
359	        return "sch = kicad.get_schematic_by_project_path(" + pyPath + ")\n";
360	
361	    // aApp == "pcb"
362	    return "board = kicad.get_board_by_project_path(" + pyPath + ")\n";
363	}
