100	// Build mode-specific Python init code (kipy imports + editor connection).
101	// socketPath is empty for sync execution, set for async (known socket).
102	static std::string BuildModeInitCode( const wxString& aMode, const std::string& aSocketPath = "" )
103	{
104	    std::string socketArg;
105	    if( !aSocketPath.empty() )
106	    {
107	        // Escape backslashes for Python string literal (Windows paths)
108	        std::string escaped = aSocketPath;
109	        for( size_t pos = 0; ( pos = escaped.find( '\\', pos ) ) != std::string::npos; pos += 2 )
110	            escaped.insert( pos, "\\" );
111	        socketArg = "socket_path='" + escaped + "', timeout_ms=5000";
112	    }
113	
114	    std::string initCode = KIPY_BOOTSTRAP +
115	        "import kipy\n"
116	        "from kipy.geometry import Vector2\n"
117	        "kicad = kipy.KiCad(" + socketArg + ")\n";
118	
119	    if( aMode == "sch" )
120	    {
121	        // Forgiving bootstrap: if no regular schematic editor responds,
122	        // bind sch=None and stash the error. The BuildIPCCommand target
123	        // preamble may rebind sch to a sub-project's editor or to the
124	        // MBS document (target.doc_type:"mbs"). The script's
125	        // refresh_or_fail(sch) raises a clear error if sch is still None
126	        // when the script first uses it.
127	        initCode +=
128	            "try:\n"
129	            "    sch = kicad.get_schematic()\n"
130	            "    if hasattr(sch, 'refresh_document'):\n"
131	            "        sch.refresh_document()\n"
132	            "    _sch_bootstrap_err = None\n"
133	            "except Exception as _e:\n"
134	            "    sch = None\n"
135	            "    _sch_bootstrap_err = _e\n";
136	    }
137	    else if( aMode == "mbs" )
138	    {
139	        // Multi-board schematic mode. The bound `mbs` variable is a kipy
140	        // Schematic targeting the .kicad_mbs document, so all standard
141	        // schematic operations (mbs.symbols.add, mbs.wiring.add_wire,
142	        // mbs.labels.add, etc.) work because the on-disk format is shared
143	        // with .kicad_sch. MBS-only operations live under mbs.multi_board.
144	        //
145	        // When the MBSCH frame isn't open, the kipy lookup fails. The
146	        // recovery path the LLM should take is documented in core.md:
147	        //   1. call check_status -> container.mbs_file_path
148	        //   2. call open_editor with editor_type:"sch" + that file_path
149	        //      (Phase A peer-window logic opens it alongside any
150	        //       sub-project editor without closing them)
151	        //   3. retry the mbs_* tool
152	        initCode +=
153	            "try:\n"
154	            "    mbs = kicad.get_mbs_schematic()\n"
155	            "    if hasattr(mbs, 'refresh_document'):\n"
156	            "        mbs.refresh_document()\n"
157	            "except Exception:\n"
158	            "    raise RuntimeError("
159	            "'No MBS schematic editor is open. Recovery: "
160	            "(1) call check_status to get container.mbs_file_path; "
161	            "(2) call open_editor with editor_type=\"sch\" and that file_path "
162	            "(opens as a peer window — does not close any sub-project editor); "
163	            "(3) retry this tool.')\n";
164	    }
165	    else if( aMode == "pcb" )
166	    {
167	        initCode +=
168	            "try:\n"
169	            "    board = kicad.get_board()\n"
170	            "except Exception:\n"
171	            "    raise RuntimeError('PCB editor is not open. Use launch_editor to open it first.')\n";
172	    }
173	
174	    return initCode;
175	}
