178	// Wait for a headless Python execution to complete, polling wxYield for UI responsiveness.
179	static std::string WaitForPythonResult( HEADLESS_PYTHON_EXECUTOR* aExecutor,
180	                                        long aTimeoutMs = 30000 )
181	{
182	    wxLongLong startTime = wxGetLocalTimeMillis();
183	
184	    while( aExecutor->IsPythonRunning() )
185	    {
186	        wxMilliSleep( 50 );
187	        wxYield();
188	
189	        if( wxGetLocalTimeMillis() - startTime > aTimeoutMs )
190	            return "Error: Python execution timed out after 30 seconds";
191	    }
192	
193	    std::string result = aExecutor->GetLastPythonResult();
194	    return result.empty() ? "(no output)" : result;
195	}
