198	// Map an editor mode string to a FRAME_T.  Returns FRAME_T(-1) for unknown modes.
199	// Used to route MAIL_AGENT_BEGIN/END_TRANSACTION + take_snapshot / detect_changes
200	// mails to the editor that's actually being modified, so the agent diff view
201	// renders for the right canvas.
202	static FRAME_T ModeToFrameType( const std::string& aMode )
203	{
204	    if( aMode == "sch" )
205	        return FRAME_SCH;
206	    if( aMode == "pcb" )
207	        return FRAME_PCB_EDITOR;
208	    if( aMode == "mbs" )
209	        return FRAME_MBSCH;
210	    return static_cast<FRAME_T>( -1 );
211	}
