            result_json = json.loads(result_str)
            img = result_json.get("image", {})
            b64_data = img.get("base64", "")
            if b64_data:
                content = [ImageContent(type="image", data=b64_data, mimeType=img.get("media_type", "image/png"))]
                text = result_json.get("text", "")

