432	    std::string replyString;
433	
434	    if( !request.ParseFromString( aRequestString ) )
435	    {
436	        ApiResponse error;
437	        error.mutable_header()->set_kicad_token( m_token );
438	        error.mutable_status()->set_status( ApiStatusCode::AS_BAD_REQUEST );
439	        error.mutable_status()->set_error_message( "request could not be parsed" );
440	        replyString = error.SerializeAsString();
441	
442	        if( ADVANCED_CFG::GetCfg().m_EnableAPILogging )
443	            log( "Response (ERROR): " + error.Utf8DebugString() );
444	    }
445	    else
446	    {
447	        if( ADVANCED_CFG::GetCfg().m_EnableAPILogging )
448	            log( "Request: " + request.Utf8DebugString() );
449	
450	        if( !request.header().kicad_token().empty() && request.header().kicad_token().compare( m_token ) != 0 )
451	        {
452	            ApiResponse error;
453	            error.mutable_header()->set_kicad_token( m_token );
454	            error.mutable_status()->set_status( ApiStatusCode::AS_TOKEN_MISMATCH );
455	            error.mutable_status()->set_error_message(
456	                    "the provided kicad_token did not match this KiCad instance's token" );
