// MOON-XXXX diagnostic instrumentation: timestamped fprintf to stderr at
// every step of the Python execution path. We're chasing a regression where
// the Python thread takes 120s to finish after its IPC calls complete in
// <100ms (introduced by the KiCad 10.0.3 upstream merge). The wxLog channel
// gets buffered/redirected during embedded execution; raw stderr survives.
// Remove these once the hang is localized.
#define PETLOG( fmt, ... )                                                     \
    do {                                                                       \
        wxString _ts = wxDateTime::UNow().Format( "%H:%M:%S.%l" );             \
        fprintf( stderr, "[%s] PETHREAD: " fmt "\n",                           \
                 (const char*) _ts.utf8_str(), ##__VA_ARGS__ );                \
        fflush( stderr );                                                      \
    } while( 0 )

